#include <vector>
#include <algorithm>

class Solution {
public:
    int longestAlternatingSubarray(std::vector<int>& nums) {
        int n = nums.size();
        if (n <= 2) return n;
        std::vector<int> pref(n, 1), suff(n, 1);
        for (int i = 1; i < n; ++i) {
            if ((nums[i] % 2 + 2) % 2 != (nums[i - 1] % 2 + 2) % 2) pref[i] = pref[i - 1] + 1;
        }
        for (int i = n - 2; i >= 0; --i) {
            if ((nums[i] % 2 + 2) % 2 != (nums[i + 1] % 2 + 2) % 2) suff[i] = suff[i + 1] + 1;
        }
        int ans = std::max(suff[1], pref[n - 2]);
        for (int i = 0; i < n; ++i) ans = std::max(ans, pref[i]);
        for (int i = 1; i < n - 1; ++i) {
            if ((nums[i - 1] % 2 + 2) % 2 != (nums[i + 1] % 2 + 2) % 2) {
                ans = std::max(ans, pref[i - 1] + suff[i + 1]);
            } else {
                ans = std::max({ans, pref[i - 1], suff[i + 1]});
            }
        }
        return ans;
    }
};

class Solution {
    public int longestAlternatingSubarray(int[] nums) {
        int n = nums.length;
        if (n <= 2) return n;
        int[] pref = new int[n];
        int[] suff = new int[n];
        java.util.Arrays.fill(pref, 1);
        java.util.Arrays.fill(suff, 1);
        for (int i = 1; i < n; i++) {
            if ((nums[i] % 2 + 2) % 2 != (nums[i - 1] % 2 + 2) % 2) pref[i] = pref[i - 1] + 1;
        }
        for (int i = n - 2; i >= 0; i--) {
            if ((nums[i] % 2 + 2) % 2 != (nums[i + 1] % 2 + 2) % 2) suff[i] = suff[i + 1] + 1;
        }
        int ans = Math.max(suff[1], pref[n - 2]);
        for (int i = 0; i < n; i++) ans = Math.max(ans, pref[i]);
        for (int i = 1; i < n - 1; i++) {
            if ((nums[i - 1] % 2 + 2) % 2 != (nums[i + 1] % 2 + 2) % 2) {
                ans = Math.max(ans, pref[i - 1] + suff[i + 1]);
            } else {
                ans = Math.max(ans, Math.max(pref[i - 1], suff[i + 1]));
            }
        }
        return ans;
    }
}

